def format_completion(self, item: CompletionItem) -> str:
    help_text = item.help.replace("\t", " ") if item.help else None
    if help_text:
        return f"{item.type},{item.value}\t{help_text}"
    return f"{item.type},{item.value}"

def _get_illegal_split_indices(self, string: str) -> set[Index]:
    illegal_indices: set[Index] = set()
    iterators = [
        self._iter_fexpr_slices(string),
        self._iter_nameescape_slices(string),
    ]
    for it in iterators:
        for begin, end in it:
            illegal_indices.update(range(begin, end))
    return illegal_indices

def normalize_invisible_parens(
    node: Node, parens_after: set[str], *, mode: Mode, features: Collection[Feature]
) -> None:
    """Make existing optional parentheses invisible or create new ones.

    `parens_after` is a set of string leaf values immediately after which parens
    should be put.

    Standardizes on visible parentheses for single-element tuples, and keeps
    existing visible parentheses for other tuples and generator expressions.
    """
    for pc in list_comments(node.prefix, is_endmarker=False, mode=mode):
        if contains_fmt_directive(pc.value, FMT_OFF):
            # This `node` has a prefix with `# fmt: off`, don't mess with parens.
            return

    # The multiple context managers grammar has a different pattern, thus this is
    # separate from the for-loop below. This possibly wraps them in invisible parens,
    # and later will be removed in remove_with_parens when needed.
    if node.type == syms.with_stmt:
        _maybe_wrap_cms_in_parens(node, mode, features)

    check_lpar = False
    for index, child in enumerate(list(node.children)):
        # Fixes a bug where invisible parens are not properly stripped from
        # assignment statements that contain type annotations.
        if isinstance(child, Node) and child.type == syms.annassign:
            normalize_invisible_parens(
                child, parens_after=parens_after, mode=mode, features=features
            )

        # Fixes a bug where invisible parens are not properly wrapped around
        # case blocks.
        if isinstance(child, Node) and child.type == syms.case_block:
            normalize_invisible_parens(
                child, parens_after={"case"}, mode=mode, features=features
            )

        # Add parentheses around if guards in case blocks
        if isinstance(child, Node) and child.type == syms.guard:
            normalize_invisible_parens(
                child, parens_after={"if"}, mode=mode, features=features
            )

        # Add parentheses around long tuple unpacking in assignments.
        if (
            index == 0
            and isinstance(child, Node)
            and child.type == syms.testlist_star_expr
        ):
            check_lpar = True

        if (
            index == 0
            and isinstance(child, Node)
            and child.type == syms.atom
            and node.type == syms.expr_stmt
            and not _atom_has_magic_trailing_comma(child, mode)
            and not _is_atom_multiline(child)
        ):
            if maybe_make_parens_invisible_in_atom(
                child,
                parent=node,
                mode=mode,
                features=features,
                remove_brackets_around_comma=True,
                allow_star_expr=True,
            ):
                wrap_in_parentheses(node, child, visible=False)

        if check_lpar:
            if (
                child.type == syms.atom
                and node.type == syms.for_stmt
                and isinstance(child.prev_sibling, Leaf)
                and child.prev_sibling.type == token.NAME
                and child.prev_sibling.value == "for"
            ):
                if maybe_make_parens_invisible_in_atom(
                    child,
                    parent=node,
                    mode=mode,
                    features=features,
                    remove_brackets_around_comma=True,
                ):
                    wrap_in_parentheses(node, child, visible=False)
            elif isinstance(child, Node) and node.type == syms.with_stmt:
                remove_with_parens(child, node, mode=mode, features=features)
            elif child.type == syms.atom and not (
                "in" in parens_after
                and len(child.children) == 3
                and is_lpar_token(child.children[0])
                and is_rpar_token(child.children[-1])
                and child.children[1].type == syms.test
            ):
                if maybe_make_parens_invisible_in_atom(
                    child, parent=node, mode=mode, features=features
                ):
                    wrap_in_parentheses(node, child, visible=False)
            elif is_one_tuple(child):
                wrap_in_parentheses(node, child, visible=True)
            elif node.type == syms.import_from:
                _normalize_import_from(node, child, index)
                break
            elif (
                index == 1
                and child.type == token.STAR
                and node.type == syms.except_clause
            ):
                # In except* (PEP 654), the star is actually part of
                # of the keyword. So we need to skip the insertion of
                # invisible parentheses to work more precisely.
                continue

            elif (
                isinstance(child, Leaf)
                and child.next_sibling is not None
                and child.next_sibling.type == token.COLON
                and child.value == "case"
            ):
                # A special patch for "case case:" scenario, the second occurrence
                # of case will be not parsed as a Python keyword.
                break

            elif not is_multiline_string(child):
                wrap_in_parentheses(node, child, visible=False)

        comma_check = child.type == token.COMMA

        check_lpar = isinstance(child, Leaf) and (
            child.value in parens_after or comma_check
        )

@mypyc_attr(patchable=True)

def reformat_one(
    src: Path,
    fast: bool,
    write_back: WriteBack,
    mode: Mode,
    report: "Report",
    *,
    lines: Collection[tuple[int, int]] = (),
    no_cache: bool = False,
    cache_dir: Path | None = None,
) -> None:
    """Reformat a single file under `src` without spawning child processes.

    `fast`, `write_back`, and `mode` options are passed to
    :func:`format_file_in_place` or :func:`format_stdin_to_stdout`.
    """
    try:
        changed = Changed.NO

        if str(src) == "-":
            is_stdin = True
        elif str(src).startswith(STDIN_PLACEHOLDER):
            is_stdin = True
            # Use the original name again in case we want to print something
            # to the user
            src = Path(str(src)[len(STDIN_PLACEHOLDER) :])
        else:
            is_stdin = False

        if is_stdin:
            if src.suffix == ".pyi":
                mode = replace(mode, is_pyi=True)
            elif src.suffix == ".ipynb":
                mode = replace(mode, is_ipynb=True)
            if format_stdin_to_stdout(
                fast=fast, write_back=write_back, mode=mode, lines=lines
            ):
                changed = Changed.YES
        else:
            if no_cache:
                cache = None
            elif cache_dir is None:
                cache = Cache.read(mode)
            else:
                cache = Cache.read(mode, cache_dir)
            if cache is not None and write_back not in (
                WriteBack.DIFF,
                WriteBack.COLOR_DIFF,
            ):
                if not cache.is_changed(src):
                    changed = Changed.CACHED
            if changed is not Changed.CACHED and format_file_in_place(
                src, fast=fast, write_back=write_back, mode=mode, lines=lines
            ):
                changed = Changed.YES
            if cache is not None and (
                (write_back is WriteBack.YES and changed is not Changed.CACHED)
                or (write_back is WriteBack.CHECK and changed is Changed.NO)
            ):
                cache.write([src])
        report.done(src, changed)
    except Exception as exc:
        if report.verbose:
            traceback.print_exc()
        report.failed(src, exc)

def do_splitter_match(self, line: Line) -> TMatchResult:
    LL = line.leaves

    if line.leaves[-1].type in OPENING_BRACKETS:
        return TErr(
            "Cannot wrap parens around a line that ends in an opening bracket."
        )

    string_idx = (
        self._return_match(LL)
        or self._return_annotation_match(LL)
        or self._else_match(LL)
        or self._assert_match(LL)
        or self._assign_match(LL)
        or self._binary_match(line)
        or self._dict_or_lambda_match(LL)
    )

    if string_idx is None:
        string_idx = self._trailing_comma_tuple_match(line)

    if string_idx is None:
        string_idx = self._prefer_paren_wrap_match(line)

    if string_idx is not None:
        # If the string is implicitly concatenated with a string on another
        # line (e.g. raw strings, which StringMerger leaves alone), wrapping
        # it in parens on its own would produce invalid code.
        next_sibling = LL[string_idx].next_sibling
        if next_sibling is not None and next_sibling.type == token.STRING:
            if not any(leaf is next_sibling for leaf in LL):
                return TErr(
                    "Cannot wrap a string that is implicitly concatenated with a"
                    " string on another line."
                )

            # Wrapping would move the first string's comments to the LPAR.
            if line.comments:
                return TErr(
                    "Cannot wrap an implicit concatenation that has comments."
                )

            # If the first string fits on the line, splitting at the
            # concatenation is enough.
            tail = "".join(str(leaf) for leaf in LL[string_idx + 1 :])
            if (
                str_width(line_to_string(line)) - str_width(tail)
                <= self.line_length
            ):
                return TErr(
                    "The first string of the implicit concatenation fits on"
                    " the line."
                )

        string_value = line.leaves[string_idx].value
        # If the string has neither spaces nor East Asian stops...
        if not any(
            char == " " or char in SPLIT_SAFE_CHARS for char in string_value
        ):
            # And will still violate the line length limit when split...
            max_string_width = self.line_length - ((line.depth + 1) * 4)
            if str_width(string_value) > max_string_width:
                # And has no associated custom splits...
                if not self.has_custom_splits(string_value):
                    # Then we should NOT put this string on its own line.
                    return TErr(
                        "We do not wrap long strings in parentheses when the"
                        " resultant line would still be over the specified line"
                        " length and can't be split further by StringSplitter."
                    )
        return Ok([string_idx])

    return TErr("This line does not contain any non-atomic strings.")

def _is_valid_standalone_fmt_comment(
    comment: ProtoComment, leaf: Leaf, is_fmt_off: bool, is_fmt_skip: bool
) -> bool:
    """Check if comment is a valid standalone fmt directive.

    We only want standalone comments. If there's no previous leaf or if
    the previous leaf is indentation, it's a standalone comment in disguise.
    """
    # A comment that is already a standalone comment node is always valid.
    if comment.type == STANDALONE_COMMENT:
        return True

    # If the leaf itself is a comment, we need to check the preceding leaf.
    if leaf.type != COMMENT:
        return True

    prev = preceding_leaf(leaf)
    if not prev:
        return True

    # Treat STANDALONE_COMMENT nodes as whitespace for check
    if is_fmt_off and prev.type not in WHITESPACE and prev.type != STANDALONE_COMMENT:
        return False
    if is_fmt_skip and prev.type in WHITESPACE:
        return False

    return True

@decorators.raise_if_nothing_inferred
def _infer(
    self, context: InferenceContext | None = None, **kwargs: Any
) -> Generator[InferenceResult]:
    """Support IfExp inference.

    If we can't infer the truthiness of the condition, we default
    to inferring both branches. Otherwise, we infer either branch
    depending on the condition.
    """
    both_branches = False
    # We use two separate contexts for evaluating lhs and rhs because
    # evaluating lhs may leave some undesired entries in context.path
    # which may not let us infer right value of rhs.

    context = context or InferenceContext()
    lhs_context = copy_context(context)
    rhs_context = copy_context(context)
    try:
        test = next(self.test.infer(context=context.clone()))
    except (InferenceError, StopIteration):
        both_branches = True
    else:
        test_bool_value = test.bool_value()
        if not isinstance(test, util.UninferableBase) and not isinstance(
            test_bool_value, util.UninferableBase
        ):
            if test_bool_value:
                yield from self.body.infer(context=lhs_context)
            else:
                yield from self.orelse.infer(context=rhs_context)
        else:
            both_branches = True
    if both_branches:
        yield from self.body.infer(context=lhs_context)
        yield from self.orelse.infer(context=rhs_context)

def _get_position_info(
    self,
    node: ast.ClassDef | ast.FunctionDef | ast.AsyncFunctionDef,
    parent: nodes.ClassDef | nodes.FunctionDef | nodes.AsyncFunctionDef,
) -> Position | None:
    """Return position information for ClassDef and FunctionDef nodes.

    In contrast to AST positions, these only include the actual keyword(s)
    and the class / function name.

    >>> @decorator
    >>> async def some_func(var: int) -> None:
    >>> ^^^^^^^^^^^^^^^^^^^
    """
    if not self._data:
        return None
    # Determine the end line of the node. For a node with a body, the
    # position should end at the last line of the body, not the first.
    if node.body:
        end_lineno = node.body[-1].lineno
    else:
        end_lineno = node.end_lineno
    data = "\n".join(self._data[node.lineno - 1 : end_lineno])

    start_token: TokenInfo | None = None
    keyword_tokens: tuple[int, ...] = (token.NAME,)
    if isinstance(parent, nodes.AsyncFunctionDef):
        search_token = "async"
    elif isinstance(parent, nodes.FunctionDef):
        search_token = "def"
    else:
        search_token = "class"

    for t in generate_tokens(StringIO(data).readline):
        if (
            start_token is not None
            and t.type == token.NAME
            and t.string == node.name
        ):
            break
        if t.type in keyword_tokens:
            if t.string == search_token:
                start_token = t
                continue
            # Skip the 'def' keyword that follows 'async' when parsing
            # an async function definition.
            if isinstance(parent, nodes.AsyncFunctionDef) and t.string == "def":
                continue
        start_token = None
    else:
        return None

    return Position(
        lineno=node.lineno + start_token.start[0] - 1,
        col_offset=start_token.start[1],
        end_lineno=node.lineno + t.end[0] - 1,
        end_col_offset=t.end[1],
    )

