@_warn_spider_arg
def process_request(
    self, request: Request, spider: Spider | None = None
) -> Request | Response | None:
    if request.meta.get("dont_cache", False):
        return None

    # Skip uncacheable requests
    if not self.policy.should_cache_request(request):
        request.meta["dont_cache"] = True  # flag as uncacheable
        return None

    # Look for cached response and check if expired
    cachedresponse: Response | None = self.storage.retrieve_response(
        self.crawler.spider, request
    )
    if cachedresponse is None:
        self.stats.inc_value("httpcache/miss")
        if self.ignore_missing:
            self.stats.inc_value("httpcache/ignore")
            raise IgnoreRequest(f"Ignored request not in cache: {request}")
        return None  # first time request

    # Return cached response only if not expired
    cachedresponse.flags.append("cached")
    if self.policy.is_cached_response_fresh(cachedresponse, request):
        self.stats.inc_value("httpcache/hit")
        return cachedresponse

    # Keep a reference to cached response to avoid a second cache lookup on
    # process_response hook
    request.meta["cached_response"] = cachedresponse

    return None

def add_cookie_header(self, request: Request) -> None:
    wreq = WrappedRequest(request)
    self.policy._now = self.jar._now = time.time()  # type: ignore[attr-defined]

    # the cookiejar implementation iterates through all domains
    # instead we restrict to potential matches on the domain
    req_host = urlparse_cached(request).hostname
    if not req_host:
        return

    if not IPV4_RE.search(req_host):
        hosts = potential_domain_matches(req_host)
        if "." not in req_host:
            hosts.append(req_host + ".local")
    else:
        hosts = [req_host]

    cookies = []
    for host in hosts:
        if host in self.jar._cookies:  # type: ignore[attr-defined]
            cookies.extend(self.jar._cookies_for_domain(host, wreq))  # type: ignore[attr-defined]

    attrs = self.jar._cookie_attrs(cookies)  # type: ignore[attr-defined]
    if attrs and not wreq.has_header("Cookie"):
        wreq.add_unredirected_header("Cookie", "; ".join(attrs))

    self.processed += 1
    if self.processed % self.check_expired_frequency == 0:
        # This is still quite inefficient for large number of cookies
        self.jar.clear_expired_cookies()

def __setitem__(self, key: _KT, value: _VT) -> None:
    if self.limit is not None:
        if self.limit == 0:
            raise ValueError("Limit cannot be zero")
        while len(self) >= self.limit:
            self.popitem(last=False)
    super().__setitem__(key, value)

def create_sql(self, expression: exp.Create) -> str:
    kind = expression.kind
    exists = expression.args.get("exists", None)

    like_property = expression.find(exp.LikeProperty)
    if like_property:
        ctas_expression = like_property.this
    else:
        ctas_expression = expression.expression

    if kind == "VIEW":
        expression.this.set("catalog", None)
        with_ = expression.args.get("with")
        if ctas_expression and with_:
            # We've already preprocessed the Create expression to bubble up any nested CTEs,
            # but CREATE VIEW actually requires the WITH clause to come after it so we need
            # to amend the AST by moving the CTEs to the CREATE VIEW statement's query.
            ctas_expression.set("with", with_.pop())

    sql = super().create_sql(expression)

    table = expression.find(exp.Table)

    # Convert CTAS statement to SELECT .. INTO ..
    if kind == "TABLE" and ctas_expression:
        if isinstance(ctas_expression, exp.UNWRAPPED_QUERIES):
            ctas_expression = ctas_expression.subquery()

        properties = expression.args.get("properties") or exp.Properties()
        is_temp = any(isinstance(p, exp.TemporaryProperty) for p in properties.expressions)

        select_into = exp.select("*").from_(exp.alias_(ctas_expression, "temp", table=True))
        select_into.set("into", exp.Into(this=table, temporary=is_temp))

        if like_property:
            select_into.limit(0, copy=False)

        sql = self.sql(select_into)

    if exists:
        identifier = self.sql(exp.Literal.string(exp.table_name(table) if table else ""))
        sql_with_ctes = self.prepend_ctes(expression, sql)
        sql_literal = self.sql(exp.Literal.string(sql_with_ctes))
        if kind == "SCHEMA":
            return f"""IF NOT EXISTS (SELECT * FROM information_schema.schemata WHERE schema_name = {identifier}) EXEC({sql_literal})"""
        elif kind == "TABLE":
            assert table
            where = exp.and_(
                exp.column("table_name").eq(table.name),
                exp.column("table_schema").eq(table.db) if table.db else None,
                exp.column("table_catalog").eq(table.catalog) if table.catalog else None,
            )
            return f"""IF NOT EXISTS (SELECT * FROM information_schema.tables WHERE {where}) EXEC({sql_literal})"""
        elif kind == "INDEX":
            index = self.sql(exp.Literal.string(expression.this.text("this")))
            return f"""IF NOT EXISTS (SELECT * FROM sys.indexes WHERE object_id = object_id({identifier}) AND name = {index}) EXEC({sql_literal})"""
    elif expression.args.get("replace"):
        sql = sql.replace("CREATE OR REPLACE ", "CREATE OR ALTER ", 1)

    return self.prepend_ctes(expression, sql)

def datatype_sql(self, expression: exp.DataType) -> str:
    # Check if this is a temporal type that needs precision handling. Fabric limits temporal
    # types to max 6 digits precision. When no precision is specified, we default to 6 digits.
    if expression.is_type(*exp.DataType.TEMPORAL_TYPES):
        # Get the current precision (first expression if it exists)
        precision_param = expression.find(exp.DataTypeParam)
        target_precision = 6

        if precision_param and precision_param.this.is_int:
            # Cap precision at 6
            current_precision = precision_param.this.to_py()
            target_precision = min(current_precision, 6)
        else:
            # If precision exists but is not an integer, default to 6
            target_precision = 6

        # Create a new expression with the target precision
        expression = exp.DataType(
            this=expression.this,
            expressions=[exp.DataTypeParam(this=exp.Literal.number(target_precision))],
        )

    return super().datatype_sql(expression)

def _parse_group(self, skip_group_by_token: bool = False) -> t.Optional[exp.Group]:
    if not skip_group_by_token and not self._match(TokenType.GROUP_BY):
        return None
    comments = self._prev_comments

    elements: t.Dict[str, t.Any] = defaultdict(list)
    # Ensure all expected keys are initialized
    elements["expressions"] = []
    elements["rollup"] = []
    elements["cube"] = []
    elements["grouping_sets"] = []

    if self._match(TokenType.ALL):
        elements["all"] = True
    elif self._match(TokenType.DISTINCT):
        elements["all"] = False

    while True:
        index = self._index

        elements["expressions"].extend(
            self._parse_csv(
                lambda: None
                if self._match_set((TokenType.CUBE, TokenType.ROLLUP), advance=False)
                else self._parse_assignment()
            )
        )

        before_with_index = self._index
        with_prefix = self._match(TokenType.WITH)

        if self._match(TokenType.ROLLUP):
            elements["rollup"].append(
                self._parse_cube_or_rollup(exp.Rollup, with_prefix=with_prefix)
            )
        elif self._match(TokenType.CUBE):
            elements["cube"].append(
                self._parse_cube_or_rollup(exp.Cube, with_prefix=with_prefix)
            )
        elif self._match(TokenType.GROUPING_SETS):
            elements["grouping_sets"].append(
                self.expression(
                    exp.GroupingSets,
                    expressions=self._parse_wrapped_csv(self._parse_grouping_set),
                )
            )
        elif self._match_text_seq("TOTALS"):
            elements["totals"] = True  # type: ignore

        if before_with_index <= self._index <= before_with_index + 1:
            self._retreat(before_with_index)
            break

        if index == self._index:
            break

    return self.expression(exp.Group, comments=comments, **elements)  # type: ignore

def _parse_for_in(self) -> exp.ForIn:
    this = self._parse_range()
    self._match_text_seq("DO")
    return self.expression(exp.ForIn, this=this, expression=self._parse_statement())

def generate_ignored_nodes(leaf: Leaf) -> Iterator[LN]:
    """Starting from the container of `leaf`, generate all leaves until `# fmt: on`.

    Stops at the end of the block.
    """
    container: Optional[LN] = leaf.parent if leaf.type == token.COMMENT else container_of(leaf)
    while container is not None and container.type != token.ENDMARKER:
        is_fmt_on = False
        for comment in list_comments(container.prefix, is_endmarker=False):
            if comment.value in FMT_ON:
                is_fmt_on = True
            elif comment.value in FMT_OFF:
                is_fmt_on = False
        if is_fmt_on:
            return

        yield container

        container = container.next_sibling

def bracket_split_build_line(
    leaves: List[Leaf], original: Line, opening_bracket: Leaf, *, is_body: bool = False
) -> Line:
    """Return a new line with given `leaves` and respective comments from `original`.

    If `is_body` is True, the result line is one-indented inside brackets and as such
    has its first leaf's prefix normalized and a trailing comma added when expected.
    """
    result = Line(depth=original.depth)
    if is_body:
        result.inside_brackets = True
        result.depth += 1
        if leaves:
            # Since body is a new indent level, remove spurious leading whitespace.
            normalize_prefix(leaves[0], inside_brackets=True)
            # Ensure a trailing comma when expected.
            if original.is_import:
                if leaves[-1].type != token.COMMA:
                    leaves.append(Leaf(token.COMMA, ","))
    # Populate the line
    for leaf in leaves:
        result.append(leaf, preformatted=True)
        for comment_after in original.comments_after(leaf):
            result.append(comment_after, preformatted=True)
    if is_body:
        result.should_explode = should_explode(result, opening_bracket)
    return result

def get_grammars(target_versions: Set[TargetVersion]) -> List[Grammar]:
    if not target_versions:
        return GRAMMARS
    elif all(version.is_python3() for version in target_versions):
        # Python 3-compatible code, so use the full Python 3 grammar.
        return [pygram.python_grammar]
    else:
        # Python 2-compatible code, so don't try Python 3 grammar.
        return [
            pygram.python_grammar_no_print_statement_no_exec_statement,
            pygram.python_grammar_no_print_statement,
        ]

def _partially_consume_prefix(self, prefix, column):
    lines = []
    current_line = ""
    current_column = 0
    wait_for_nl = False
    for char in prefix:
        current_line += char
        if wait_for_nl:
            if char == '\n':
                if current_line.strip() and current_column <= column:
                    res = ''.join(lines)
                    return res, prefix[len(res):]
                lines.append(current_line)
                current_line = ""
                current_column = 0
                wait_for_nl = False
        elif char == ' ':
            current_column += 1
        elif char == '\t':
            current_column += 4
        elif char == '\n':
            current_column = 0
        else:
            wait_for_nl = True
    return ''.join(lines), current_line

def get_future_imports(node: Node) -> Set[str]:
    """Return a set of __future__ imports in the file."""
    imports = set()
    for child in node.children:
        if child.type != syms.simple_stmt:
            break
        first_child = child.children[0]
        if isinstance(first_child, Leaf):
            # Continue looking if we see a docstring; otherwise stop.
            if (
                len(child.children) == 2
                and first_child.type == token.STRING
                and child.children[1].type == token.NEWLINE
            ):
                continue
            else:
                break
        elif first_child.type == syms.import_from:
            module_name = first_child.children[1]
            if not isinstance(module_name, Leaf) or module_name.value != "__future__":
                break
            for import_from_child in first_child.children[3:]:
                if isinstance(import_from_child, Leaf):
                    if import_from_child.type == token.NAME:
                        imports.add(import_from_child.value)
                    elif import_from_child.type == token.COMMA:
                        # Skip commas between names
                        continue
                else:
                    assert import_from_child.type == syms.import_as_names
                    for leaf in import_from_child.children:
                        if isinstance(leaf, Leaf) and leaf.type == token.NAME:
                            imports.add(leaf.value)
        else:
            break
    return imports

def gen_python_files_in_dir(
    path: Path,
    root: Path,
    include: Pattern[str],
    exclude: Pattern[str],
    report: "Report",
) -> Iterator[Path]:
    """Generate all files under `path` whose paths are not excluded by the
    `exclude` regex, but are included by the `include` regex.

    `report` is where output about exclusions goes.
    """
    assert root.is_absolute(), f"INTERNAL ERROR: `root` must be absolute but is {root}"
    for child in path.iterdir():
        try:
            resolved = child.resolve(strict=False)
        except RuntimeError:
            # circular symlink
            report.path_ignored(child, "circular symlink")
            continue
        normalized_path = "/" + resolved.relative_to(root).as_posix()
        if child.is_dir():
            normalized_path += "/"
        exclude_match = exclude.search(normalized_path)
        if exclude_match and exclude_match.group(0):
            report.path_ignored(child, f"matches the --exclude regular expression")
            continue

        if child.is_dir() and not child.is_symlink():
            yield from gen_python_files_in_dir(child, root, include, exclude, report)

        elif child.is_file():
            include_match = include.search(normalized_path)
            if include_match:
                yield child

def _maybe_empty_lines(self, current_line: Line) -> Tuple[int, int]:
    max_allowed = 1
    if current_line.depth == 0:
        max_allowed = 2
    if current_line.leaves:
        # Consume the first leaf's extra newlines.
        first_leaf = current_line.leaves[0]
        before = first_leaf.prefix.count("\n")
        before = min(before, max_allowed)
        first_leaf.prefix = ""
    else:
        before = 0
    depth = current_line.depth
    while self.previous_defs and self.previous_defs[-1] >= depth:
        self.previous_defs.pop()
        before = 1 if depth else 2
    is_decorator = current_line.is_decorator
    if is_decorator or current_line.is_def or current_line.is_class:
        if not is_decorator:
            self.previous_defs.append(depth)
        if self.previous_line is None:
            # Don't insert empty lines before the first line in the file.
            return 0, 0

        if self.previous_line and self.previous_line.is_decorator:
            # Don't insert empty lines between decorators.
            return 0, 0

        newlines = 2
        if current_line.depth:
            newlines -= 1
        return newlines, 0

    if current_line.is_flow_control:
        return before, 1

    if (
        self.previous_line
        and self.previous_line.is_import
        and not current_line.is_import
        and depth == self.previous_line.depth
    ):
        return (before or 1), 0

    if (
        self.previous_line
        and self.previous_line.is_yield
        and (not current_line.is_yield or depth != self.previous_line.depth)
    ):
        return (before or 1), 0

    return before, 0

def dump_to_file(*output: str) -> str:
    """Dump `output` to a temporary file. Return path to the file."""
    import tempfile

    with tempfile.NamedTemporaryFile(
        mode="w", prefix="blk_", suffix=".log", delete=False
    ) as f:
        for line in output:
            f.write(line)
            if line and line[-1] != "\n":
                f.write("\n")
    return f.name

def get_host_regex(self, spider):
    """Override this method to implement a different offsite policy"""
    allowed_domains = getattr(spider, 'allowed_domains', None)
    if not allowed_domains:
        return re.compile('')
    url_pattern = re.compile(r'^https?://.*$')
    for domain in allowed_domains:
        if url_pattern.match(domain):
            message = (
                "allowed_domains accepts only domains, not URLs. "
                "Ignoring URL entry %s in allowed_domains." % domain
            )
            warnings.warn(message, URLWarning)
    domains = [re.escape(d) for d in allowed_domains if d is not None and not url_pattern.match(d)]
    if not domains:
        return re.compile('')
    regex = r'^(.*\.)?(%s)$' % '|'.join(domains)
    return re.compile(regex)

def __setitem__(self, key, value):
    while len(self) >= self.limit:
        self.popitem(last=False)
    super().__setitem__(key, value)

def process_response(self, request, response, spider):
    if (request.meta.get('dont_redirect', False) or
            response.status in getattr(spider, 'handle_httpstatus_list', []) or
            response.status in request.meta.get('handle_httpstatus_list', []) or
            request.meta.get('handle_httpstatus_all', False)):
        return response

    allowed_status = (301, 302, 303, 307, 308)
    if 'Location' not in response.headers or response.status not in allowed_status:
        return response

    location = safe_url_string(response.headers['Location'])

    redirected_url = urljoin(request.url, location)

    if response.status in (301, 307, 308) or request.method == 'HEAD':
        redirected = request.replace(url=redirected_url)
        return self._redirect(redirected, request, spider, response.status)

    redirected = self._redirect_request_using_get(request, redirected_url)
    return self._redirect(redirected, request, spider, response.status)

def convert_image(self, image, size=None):
    if image.format == 'PNG' and image.mode == 'RGBA':
        background = Image.new('RGB', image.size, (255, 255, 255))
        background.paste(image, mask=image.split()[3])
        image = background
    elif image.mode != 'RGB':
        image = image.convert('RGB')

    if size:
        image = image.copy()
        image.thumbnail(size, Image.LANCZOS)

    buf = BytesIO()
    image.save(buf, 'JPEG')
    return image, buf

def _get_form_url(form, url):
    if not url:
        action = form.action or ''
        return urljoin(form.base_url, action)
    return urljoin(form.base_url, url)

def __new__(mcs, class_name, bases, attrs):
    new_bases = tuple(base._class for base in bases if hasattr(base, '_class'))
    _class = super(ItemMeta, mcs).__new__(mcs, 'x_' + class_name, new_bases, attrs)

    fields = getattr(_class, 'fields', {})
    new_attrs = {}
    for n, v in attrs.items():
        if isinstance(v, Field):
            fields[n] = v
        else:
            new_attrs[n] = v

    new_attrs['fields'] = fields
    new_attrs['_class'] = _class
    return super(ItemMeta, mcs).__new__(mcs, class_name, bases, new_attrs)

